# Keep atlas geometry and a later research classification separate: Ningde is not a registration failure.
for f in FEATURES:
 if f['properties']['id'] in ['min-mindong-houguan','min-mindong-funing']:
  f['properties']['evidenceNote'] += ' 分类体系差异：用户提供 B12 图幅将宁德城置于侯官片斜线区；秋谷裕幸（2022）《原始闽东区方言的 *yɑi 韵及其相关问题》第77页表1将宁德列为闽东区北片／福宁小片。此处保留原图边界，不据后来的分类移动图线。来源：https://www.jstage.jst.go.jp/article/chuugokugogaku/2022/269/2022_76/_pdf#page=2 。'
  f['properties']['classificationDifferences']=[{'place':'宁德城关','atlasClassification':'B12：闽东区／侯官片','alternativeClassification':'秋谷裕幸2022：闽东区／北片／福宁小片','source':'https://www.jstage.jst.go.jp/article/chuugokugogaku/2022/269/2022_76/_pdf#page=2','page':'77，表1（PDF第2页）','sourcePixel':[1593.1,807.7],'interpretation':'classification-scheme-difference; not-georegistration-error'}]

# Validate closure / topology when Shapely is available; repair only crossings, preserving sourceBoundary.
try:
 from shapely.geometry import shape,mapping
 for f in FEATURES:
  g=shape(f['geometry'])
  if not g.is_valid:
   repaired=g.buffer(0)
   if repaired.is_empty: raise ValueError(f['properties']['id'])
   f['geometry']=mapping(repaired);f['properties']['topologyRepair']='buffer-zero for manually traced crossing'
except ImportError: pass
out=ROOT/'dist/data';out.mkdir(exist_ok=True,parents=True)
(out/'regions-south.geojson').write_text(json.dumps({'type':'FeatureCollection','features':FEATURES},ensure_ascii=False,separators=(',',':')),encoding='utf-8')
